import React from "react";
import { 
  useCurrentFrame, 
  useVideoConfig, 
  AbsoluteFill, 
  interpolate, 
  Img, 
  Easing 
} from '../remotionShim';
// Font Loader Hook
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// Schema Definition


export type FloatingPolaroidProps = Record<string, any>;

const FloatingPolaroid: React.FC<FloatingPolaroidProps> = ({
  backgroundColor = "#1a1a1a",
  transparentBackground = true,
  durationInSeconds = 8,
  imageUrl = "https://images.unsplash.com/photo-1542206395-9feb3edaa68d?q=80&w=1000&auto=format&fit=crop",
  caption = "Summer Vibes",
  backColor = "#ff6b6b",
  flipDelayInSeconds = 1.0,
  flipDurationInSeconds = 1.5,
  cardScale = 0.8,
}) => {
  // Load Fonts
  useFontLoader(["Permanent Marker"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color Handling
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation Timing
  // We repurpose 'flipDelay' as the start time of the throw animation
  const startFrame = flipDelayInSeconds * fps;
  const throwDuration = flipDurationInSeconds * fps;
  const endFrame = startFrame + throwDuration;

  // 1. Z-Axis Translation (The Approach)
  // Moves from deep background (-1500px) to foreground (0px)
  const translateZ = interpolate(
    frame,
    [startFrame, endFrame],
    [-1500, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic), // Smooth deceleration like a thrown object
    }
  );

  // 2. Y-Axis Translation (The Arc)
  // Starts lower (dropped/thrown from below) and rises to center
  const throwY = interpolate(
    frame,
    [startFrame, endFrame],
    [500, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  // 3. Rotation Y (The Flip)
  // Starts facing away (approx 195deg to add slight asymmetry), rotates to front (0deg)
  const rotateY = interpolate(
    frame,
    [startFrame, endFrame],
    [195, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.cubic),
    }
  );

  // 4. Rotation Z (The Tumble)
  // A slight tilt that straightens out as it lands
  const rotateZ = interpolate(
    frame,
    [startFrame, endFrame],
    [-25, 0],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
      easing: Easing.out(Easing.back(1.2)), // Slight overshoot to settle naturally
    }
  );

  // 5. Floating Logic (The Bobbing)
  // Continuous sine wave motion
  const floatAmplitude = 15; 
  const floatFrequency = 0.05; 
  // Dampen the float during the violent throw movement, ramp it up as it settles
  const floatDampener = interpolate(
    frame,
    [startFrame, endFrame],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  const floatY = Math.sin(frame * floatFrequency) * floatAmplitude * floatDampener;

  // Combine motions
  const finalTranslateY = throwY + floatY;

  // 6. Dynamic Shadow
  // Shadow intensity depends on both rotation (angle of light) and distance (Z-depth)
  
  // Angle logic: stronger shadow when flat (0/180), weaker when edge-on (90)
  // Note: We use modulo 180 logic implicitly via the range map for the flip
  const angleShadowOpacity = interpolate(
    Math.abs((rotateY % 180) - 90), 
    [0, 90],
    [0.1, 0.4],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  
  // Distance logic: fade shadow as object moves further away
  const distShadowOpacity = interpolate(
    translateZ,
    [-1500, 0],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const finalShadowOpacity = angleShadowOpacity * distShadowOpacity;

  const shadowBlur = interpolate(
    Math.abs((rotateY % 180) - 90),
    [0, 90],
    [20, 50],
    { extrapolateRight: "clamp" }
  );

  // Dimensions
  const cardWidth = Math.min(width, height) * 0.5 * cardScale; 
  const cardHeight = cardWidth * 1.25; // Typical polaroid aspect ratio approx 1:1.25
  const borderWidth = cardWidth * 0.05;
  const bottomBorder = cardWidth * 0.2; // Thicker bottom for caption

  const containerStyle: React.CSSProperties = {
    perspective: "1200px",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    width: "100%",
    height: "100%",
    backgroundColor: bgColor,
    fontFamily: "Permanent Marker",
  };

  const cardWrapperStyle: React.CSSProperties = {
    width: cardWidth,
    height: cardHeight,
    position: "relative",
    transformStyle: "preserve-3d",
    // 3D Transform Composition
    transform: `translateY(${finalTranslateY}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) rotateZ(${rotateZ}deg)`,
    transition: "none", // Forbidden in Remotion
  };

  const faceStyle: React.CSSProperties = {
    position: "absolute",
    width: "100%",
    height: "100%",
    backfaceVisibility: "hidden", // Crucial for flip
    borderRadius: "4px",
    boxShadow: `0px 20px ${shadowBlur}px rgba(0,0,0,${finalShadowOpacity})`,
    overflow: "hidden",
  };

  const frontFaceStyle: React.CSSProperties = {
    ...faceStyle,
    backgroundColor: "#ffffff",
    display: "flex",
    flexDirection: "column",
    alignItems: "center",
    justifyContent: "flex-start",
    padding: borderWidth,
    paddingBottom: bottomBorder,
    transform: "rotateY(0deg)", // Front face
  };

  const backFaceStyle: React.CSSProperties = {
    ...faceStyle,
    backgroundColor: backColor,
    transform: "rotateY(180deg)", // Back face
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
  };

  // Pattern for the back of the card
  const Pattern = () => (
    <svg width="100%" height="100%" style={{ opacity: 0.2 }}>
      <defs>
        <pattern id="lines" x="0" y="0" width="20" height="20" patternUnits="userSpaceOnUse">
          <line x1="0" y1="0" x2="20" y2="20" stroke="white" strokeWidth="2" />
        </pattern>
      </defs>
      <rect width="100%" height="100%" fill="url(#lines)" />
    </svg>
  );

  return (
    <AbsoluteFill style={containerStyle}>
      <div style={cardWrapperStyle}>
        
        {/* FRONT SIDE (Image + Caption) */}
        <div style={frontFaceStyle}>
          <div 
            style={{ 
              width: "100%", 
              height: "100%", 
              overflow: "hidden", 
              backgroundColor: "#eee",
              position: "relative"
            }}
          >
            <Img 
              src={imageUrl} 
              style={{ 
                width: "100%", 
                height: "100%", 
                objectFit: "cover",
              }} 
            />
          </div>
          <div 
            style={{ 
              position: "absolute", 
              bottom: 0, 
              width: "100%", 
              height: bottomBorder, 
              display: "flex", 
              justifyContent: "center", 
              alignItems: "center",
              color: "#222",
              fontSize: `${cardWidth * 0.08}px`,
              textAlign: "center",
            }}
          >
            {caption}
          </div>
        </div>

        {/* BACK SIDE (Solid Color + Pattern) */}
        <div style={backFaceStyle}>
          <Pattern />
          <div style={{ position: "absolute", color: "white", opacity: 0.8, fontSize: cardWidth * 0.1 }}>
             ★
          </div>
        </div>

      </div>
    </AbsoluteFill>
  );
};

export default FloatingPolaroid;